scan_column_type_check.script:
(function (engine) {

	if (x_snc_codesanity.IsCheckApplicableToRecord())
	{
		var GetStringValue = x_snc_devtools.GetStringValue;
		var ScriptRemoveComments = x_snc_devtools.ScriptRemoveComments;
		var ScriptEmptyStringLiterals = x_snc_devtools.ScriptEmptyStringLiterals;
		var StringCheckRegEx = x_snc_devtools.StringCheckRegEx;

		var strSource = GetStringValue(engine.columnValue);

		strSource = ScriptRemoveComments(strSource);
		strSource = ScriptEmptyStringLiterals(strSource);		

		if (StringCheckRegEx(strSource,'\\.\\s*addHighMessage\\s*\\(','') == true)
		{
			engine.finding.increment();
		}
		if (StringCheckRegEx(strSource,'\\.\\s*addModerateMessage\\s*\\(','') == true)
		{
			engine.finding.increment();
		}		
		if (StringCheckRegEx(strSource,'\\.\\s*addLowMessage\\s*\\(','') == true)
		{
			engine.finding.increment();
		}	
		if (StringCheckRegEx(strSource,'\\.\\s*addSuccessMessage\\s*\\(','') == true)
		{
			engine.finding.increment();
		}				

	}

})(engine);
